create extension if not exists "pgcrypto";
create table if not exists profiles (id uuid primary key default gen_random_uuid(), name text not null, headline text not null, bio text not null, strengths text[] not null default '{}', portrait_url text default '', available boolean not null default true, email text not null, phone text not null, social jsonb not null default '{}');
create table if not exists projects (id uuid primary key default gen_random_uuid(), tag text not null, title text not null, description text not null, url text, sort_order int not null default 0);
create table if not exists posts (id uuid primary key default gen_random_uuid(), tag text not null, title text not null, excerpt text not null, content text, slug text unique not null, published_at date not null default current_date);
create table if not exists travel_places (id uuid primary key default gen_random_uuid(), title text not null, visited_on date not null, description text not null, latitude double precision not null, longitude double precision not null);
create table if not exists contacts (id uuid primary key default gen_random_uuid(), label text not null, value text not null, href text not null, icon text not null, sort_order int not null default 0);
alter table profiles enable row level security; alter table projects enable row level security; alter table posts enable row level security; alter table travel_places enable row level security; alter table contacts enable row level security;
create policy "public read profiles" on profiles for select using (true); create policy "public read projects" on projects for select using (true); create policy "public read posts" on posts for select using (true); create policy "public read travel" on travel_places for select using (true); create policy "public read contacts" on contacts for select using (true);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from auth.users where id = auth.uid() and (raw_app_meta_data->>'is_admin')::boolean = true); $$;
create policy "admins manage profiles" on profiles for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage projects" on projects for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage posts" on posts for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage travel" on travel_places for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage contacts" on contacts for all using (public.is_admin()) with check (public.is_admin());
insert into storage.buckets (id, name, public) values ('portfolio-assets','portfolio-assets',true) on conflict (id) do nothing;
create policy "public asset read" on storage.objects for select using (bucket_id = 'portfolio-assets'); create policy "admins upload assets" on storage.objects for insert with check (bucket_id = 'portfolio-assets' and public.is_admin()); create policy "admins delete assets" on storage.objects for delete using (bucket_id = 'portfolio-assets' and public.is_admin());
